{"path": "verify_matches.py", "content": """"Independent checker for ./matches.json against ./log.txt.

Re-implements the README semantics WITHOUT reusing the regex from regex.txt:
  * a line qualifies iff it contains an IPv4 address (decimal, no leading zeros,
    octets 0-255) not immediately preceded/followed by an alphanumeric char;
  * on a qualifying line, take the LAST calendar-valid YYYY-MM-DD date
    (Feb allows 29 in all years) that is not immediately preceded/followed by
    an alphanumeric char;
  * lines with no valid date contribute nothing.

Also checks that regex.txt, applied with re.findall(pattern, text, re.MULTILINE),
reproduces exactly the same list.
"""

import json
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
LOG = HERE / "log.txt"
OUT = HERE / "matches.json"
REGEX = HERE / "regex.txt"

ALNUM = set("0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
DAYS = {1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}


def bounded(text, start, end):
    """True if text[start:end] is not adjacent to an alphanumeric char."""
    if start > 0 and text[start - 1] in ALNUM:
        return False
    if end < len(text) and text[end] in ALNUM:
        return False
    return True


def find_ipv4(line):
    for m in re.finditer(r"[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+", line):
        parts = m.group(0).split(".")
        if any(len(p) > 1 and p[0] == "0" for p in parts):
            continue
        if any(int(p) > 255 for p in parts):
            continue
        if not bounded(line, m.start(), m.end()):
            continue
        return True
    return False


def find_last_date(line):
    last = None
    for m in re.finditer(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", line):
        if not bounded(line, m.start(), m.end()):
            continue
        y, mo, d = (int(x) for x in m.group(0).split("-"))
        if mo < 1 or mo > 12 or d < 1 or d > DAYS[mo]:
            continue
        last = m.group(0)
    return last


def expected():
    out = []
    for line in LOG.read_text(encoding="utf-8").splitlines():
        if not find_ipv4(line):
            continue
        d = find_last_date(line)
        if d is not None:
            out.append(d)
    return out


def main():
    exp = expected()
    got = json.loads(OUT.read_text(encoding="utf-8"))
    pattern = REGEX.read_text(encoding="utf-8").strip()
    via_regex = re.findall(pattern, LOG.read_text(encoding="utf-8"), re.MULTILINE)

    ok = True
    if got != exp:
        ok = False
        print("FAIL matches.json != expected")
        print("  expected:", exp)
        print("  actual  :", got)
    if via_regex != exp:
        ok = False
        print("FAIL regex.txt findall != expected")
        print("  expected:", exp)
        print("  regex   :", via_regex)
    if not isinstance(got, list) or not all(isinstance(x, str) for x in got):
        ok = False
        print("FAIL matches.json is not a JSON list of strings")

    if ok:
        print("PASS", len(exp), "matches:", exp)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
"}

